    <style>
      :root {
        color-scheme: light;
        --bg: #f4f7fb;
        --surface: #ffffff;
        --surface-2: #f8fafc;
        --text: #0f172a;
        --muted: #64748b;
        --border: #dbe4f0;
        --accent: #2563eb;
        --accent-soft: #dbeafe;
        --shadow: 0 18px 45px rgba(15, 23, 42, 0.08);
        --radius: 20px;
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top left, rgba(37, 99, 235, 0.12), transparent 36%),
          linear-gradient(180deg, #fbfdff 0%, var(--bg) 100%);
        min-height: 100vh;
      }

      .app-shell {
        width: min(960px, calc(100% - 32px));
        margin: 32px auto;
      }

      .hero {
        background: linear-gradient(135deg, #0f172a 0%, #1d4ed8 100%);
        color: #fff;
        padding: 32px;
        border-radius: 28px;
        box-shadow: var(--shadow);
        margin-bottom: 24px;
      }

      .hero h1 {
        margin: 0 0 10px;
        font-size: clamp(2rem, 4vw, 3rem);
        line-height: 1.05;
      }

      .hero p {
        margin: 0;
        max-width: 60ch;
        color: rgba(255, 255, 255, 0.84);
      }

      form {
        display: grid;
        gap: 18px;
      }

      .card {
        background: var(--surface);
        border: 1px solid rgba(219, 228, 240, 0.9);
        border-radius: var(--radius);
        box-shadow: var(--shadow);
        overflow: hidden;
      }

      .card-inner {
        padding: 24px;
      }

      .form-field {
        background: var(--surface);
        border: 1px solid var(--border);
        border-radius: 24px;
        padding: 22px;
        display: grid;
        gap: 16px;
      }

      .question-head {
        display: grid;
        gap: 8px;
      }

      .question-title {
        margin: 0;
        font-size: 1.1rem;
      }

      .help-text {
        margin: 0;
        color: var(--muted);
        font-size: 0.95rem;
      }

      .choices {
        display: grid;
        gap: 12px;
      }

      .choice {
        display: flex;
        align-items: flex-start;
        gap: 12px;
        padding: 14px 16px;
        border: 1px solid var(--border);
        border-radius: 16px;
        background: var(--surface-2);
        transition: border-color 0.2s ease, background 0.2s ease, transform 0.2s ease;
      }

      .choice:hover {
        border-color: #b6c8e3;
        transform: translateY(-1px);
      }

      .choice input {
        margin-top: 3px;
        width: 18px;
        height: 18px;
        accent-color: var(--accent);
        flex: 0 0 auto;
      }

      .choice span {
        line-height: 1.4;
      }

      .actions {
        display: flex;
        justify-content: flex-end;
        padding-top: 4px;
      }

      button {
        appearance: none;
        border: 0;
        border-radius: 999px;
        background: var(--accent);
        color: #fff;
        font: inherit;
        font-weight: 700;
        padding: 14px 22px;
        cursor: pointer;
        box-shadow: 0 10px 24px rgba(37, 99, 235, 0.28);
      }

      button:hover {
        background: #1d4ed8;
      }

      .result {
        margin-top: 8px;
        padding: 16px 18px;
        border-radius: 16px;
        background: #eff6ff;
        color: #1e3a8a;
        border: 1px solid #bfdbfe;
        display: none;
      }

      .result[data-visible="true"] {
        display: block;
      }

      @media (max-width: 640px) {
        .app-shell {
          width: min(100% - 20px, 960px);
          margin: 20px auto;
        }

        .hero,
        .card-inner,
        .form-field {
          padding: 18px;
        }
      }
    </style>
  </head>
  <body>
    <div id="app"></div>

    <script>
      const quizData = [
        {
          id: "q1",
          title: "Which of these are programming languages?",
          helpText: "Select every option that is a computer programming language.",
          choices: ["Python", "HTML", "JavaScript", "CSS"],
        },
        {
          id: "q2",
          title: "Which of these are compiled languages?",
          choices: ["C", "Rust", "Python", "Go"],
        },
        {
          id: "q3",
          title: "Which of these are used for web development?",
          choices: ["JavaScript", "Ruby", "SQL", "Markdown"],
        },
      ];

      function ChoiceItem({ questionId, choice, index }) {
        const inputId = `${questionId}-${index}`;
        return `
          <label class="choice" for="${inputId}">
            <input type="checkbox" id="${inputId}" name="${questionId}" value="${choice}">
            <span>${choice}</span>
          </label>
        `;
      }

      function QuestionCard({ question, index }) {
        const choicesMarkup = question.choices
          .map((choice, choiceIndex) => ChoiceItem({ questionId: question.id, choice, index: choiceIndex }))
          .join("");

        return `
          <div class="form-field">
            <div class="question-head">
              <h2 class="question-title">${index + 1}. ${question.title}</h2>
              ${question.helpText ? `<p class="help-text">${question.helpText}</p>` : ""}
            </div>
            <div class="choices" role="group" aria-label="${question.title}">
              ${choicesMarkup}
            </div>
          </div>
        `;
      }

      function QuizApp() {
        return `
          <main class="app-shell">
            <section class="hero" aria-labelledby="quiz-title">
              <h1 id="quiz-title">Computer Languages Quiz</h1>
              <p>Choose all answers that apply for each question, then submit your selections.</p>
            </section>

            <section class="card" aria-label="Quiz form">
              <div class="card-inner">
                <form id="quiz-form">
                  ${quizData.map((question, index) => QuestionCard({ question, index })).join("")}
                  <div class="actions">
                    <button type="submit">Submit quiz</button>
                  </div>
                  <div id="result" class="result" aria-live="polite"></div>
                </form>
              </div>
            </section>
          </main>
        `;
      }

      document.getElementById("app").innerHTML = QuizApp();

      document.getElementById("quiz-form").addEventListener("submit", (event) => {
        event.preventDefault();

        const summary = quizData
          .map((question) => {
            const selected = Array.from(document.querySelectorAll(`input[name="${question.id}"]:checked`))
              .map((input) => input.value);
            return `${question.title} — ${selected.length ? selected.join(", ") : "No answers selected"}`;
          })
          .join("\n");

        const result = document.getElementById("result");
        result.textContent = summary;
        result.dataset.visible = "true";
      });
    </script>
  </body>
</html>
